INSERT INTO mathcoe_db.topics (id,title,description,difficulty,icon,color,is_high_freq,created_at,updated_at) VALUES
	(1001,'图形类','考察学生对二维图形的识别、旋转、平移、对称（镜像）以及对三维物体重叠关系的理解。','','','blue',0,'2026-05-08 14:39:51','2026-05-13 17:05:22'),
	(1002,'数理逻辑','考察通过已知条件进行演绎推理的能力，通常包括排除法、排序、分类讨论等。','','','purple',0,'2026-05-08 14:39:51','2026-05-13 17:20:50'),
	(1003,'应用类','将数学知识应用于现实生活情境，如时间计算、货币换算、长度测量、排列组合。','','','emerald',0,'2026-05-08 14:39:51','2026-05-13 17:05:22'),
	(1004,'运算类','不仅仅是算术（加减乘除），更侧重于对数字性质的理解、等量代换（初级代数思想）和数字模式的发现。','','','rose',0,'2026-05-08 14:39:51','2026-05-13 17:05:22');
INSERT INTO mathcoe_db.questions (id,topic_id,title,content,question_type,`options`,answer,explanation,difficulty_level,source_year,tags,created_at,updated_at) VALUES
	 (174297862144,1004,'The kangaroo goes up 3 steps each time the rabbit ','{"text": "<p>The kangaroo goes up 3 steps each time the rabbit goes down 2 steps. On which step do they meet?</p><p>图中的袋鼠每向上跳 3 个台阶，兔子就会向下跳 2 个。请问它们会在哪一个台阶见面？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260509_7b4f0939.png\\" alt=\\"20260509_7b4f0939.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>3</p>", "label": "A", "format": "html"}, {"text": "<p>4</p>", "label": "B", "format": "html"}, {"text": "<p>5</p>", "label": "C", "format": "html"}, {"text": "<p>6</p>", "label": "D", "format": "html"}, {"text": "<p>7</p>", "label": "E", "format": "html"}]','D','{"text": "<p><br></p>", "format": "html"}',1,2020,'null','2026-05-08 20:19:49','2026-05-13 10:10:58'),
	 (174309875712,1001,'Mordka took a selfie in front of this castle. Whic','{"text": "<p>Mordka took a selfie in front of this castle. Which of the pictures below could be Mordka’s photo? </p><p>Mordka在这座城堡前拍了张自拍照。以下哪张图片可能是Mordka的照片？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_1f898162.png\\" alt=\\"20260508_1f898162.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_73e8d232.png\\" alt=\\"20260508_73e8d232.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_371d1960.png\\" alt=\\"20260508_371d1960.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_d3fa1527.png\\" alt=\\"20260508_d3fa1527.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_a0628952.png\\" alt=\\"20260508_a0628952.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_2eb949e5.png\\" alt=\\"20260508_2eb949e5.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2020,'null','2026-05-08 21:08:42','2026-05-13 10:10:58'),
	 (174324535296,1001,'Nelly arranged the 4 pieces to make a picture of a','{"text": "<p>Nelly arranged the 4 pieces to make a picture of a kangaroo. How are the pieces arranged?</p><p>Nelly 要把以下 4 张图片重新排列成袋鼠的画像。请问该如何排列这些图片？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_1ed65868.png\\" alt=\\"20260508_1ed65868.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_a1ec609b.png\\" alt=\\"20260508_a1ec609b.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_15708389.png\\" alt=\\"20260508_15708389.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_58b8535f.png\\" alt=\\"20260508_58b8535f.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_f388cebc.png\\" alt=\\"20260508_f388cebc.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260508_eeff414c.png\\" alt=\\"20260508_eeff414c.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2020,'null','2026-05-08 22:08:21','2026-05-13 10:10:58'),
	 (174577459200,1002,'Danial is arranging his toys in a line, as shown b','{"text": "<p>Danial is arranging his toys in a line, as shown below. The pattern repeats every five toys. Which </p><p>two toys will be next? </p><p>Danial 把他的玩具按照下图所示的顺序排成一行。每五个玩具被排列后，他再依照同样的顺序重复摆放。请问接下来是哪两个玩具？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260509_e2525cd9.png\\" alt=\\"20260509_e2525cd9.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260509_c07caf14.png\\" alt=\\"20260509_c07caf14.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260509_8a4a2c74.png\\" alt=\\"20260509_8a4a2c74.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260509_1bc38540.png\\" alt=\\"20260509_1bc38540.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260509_d5620340.png\\" alt=\\"20260509_d5620340.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260509_fd92e7e9.png\\" alt=\\"20260509_fd92e7e9.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2020,'null','2026-05-09 15:17:30','2026-05-12 11:00:36'),
	 (174578311168,1001,'Jos ́e has two cards of the same size. Card A has ','{"text": "<p>Jos ́e has two cards of the same size. Card A has four holes cut in it. Jos ́e places card A directly on top of card B. What can Jos ́e see? </p><p>Jos ́e &nbsp;拥有两张大小相同的卡片。卡片 A 上有四个小洞。Jos ́e 将卡片 A 直接放在卡片 B 的上面。请问Jos ́e 会看到什么？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260511_7bbd5d2b.png\\" alt=\\"20260511_7bbd5d2b.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260511_5a59495b.png\\" alt=\\"20260511_5a59495b.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260511_a709fc89.png\\" alt=\\"20260511_a709fc89.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260511_1b276c3f.png\\" alt=\\"20260511_1b276c3f.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260511_c25cb70f.png\\" alt=\\"20260511_c25cb70f.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260511_7b6279fc.png\\" alt=\\"20260511_7b6279fc.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2020,'null','2026-05-09 15:20:58','2026-05-13 10:10:58'),
	 (175556931584,1001,'Mary made a shape using some white cubes and 14 gr','{"text": "<p>Mary made a shape using some white cubes and 14 grey cubes. How many of these grey cubes cannot be seen in the picture? </p><p>Mary 拿了一些白色的正方体和14个灰色的正方体拼成以下形状。请问在图中还有多少个灰色的正方体是无法被看到的？ </p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_16c5a6cc.png\\" alt=\\"20260512_16c5a6cc.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>1</p>", "label": "A", "format": "html"}, {"text": "<p>3</p>", "label": "B", "format": "html"}, {"text": "<p>5</p>", "label": "C", "format": "html"}, {"text": "<p>6</p>", "label": "D", "format": "html"}, {"text": "<p>8</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 09:42:59','2026-05-13 10:10:58'),
	 (175563788288,1001,'Anna draws a picture of some shapes. Her picture c','{"text": "<p>Anna draws a picture of some shapes. Her picture contains 3 black triangles and fewer than 4 squares. Which could be Anna’s picture? </p><p>Anna画了几个图形。她的图画里有3个黑色三角形和少于4个正方形。请问以下哪张图可能是小安画的？</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_552aeb11.png\\" alt=\\"20260512_552aeb11.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_9686c32d.png\\" alt=\\"20260512_9686c32d.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_efbf84ab.png\\" alt=\\"20260512_efbf84ab.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_5d464aab.png\\" alt=\\"20260512_5d464aab.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_47560ea7.png\\" alt=\\"20260512_47560ea7.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 10:10:53','2026-05-13 10:10:58'),
	 (175577456640,1001,'The braid in the figure is composed of three threa','{"text": "<p>The braid in the figure is composed of three threads. One thread is green, one is blue and one is red. What colours are the three threads? </p><p>下图是一股由三根绳子编成的麻花绳，其中一根绳子是绿色的，一根是蓝色的，还有一根是红色的，请问带编号的这三根绳子分别都是什么颜色？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_56abff35.png\\" alt=\\"20260512_56abff35.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>1 is blue, 2 is green and 3 is red.</p><p>1 号为蓝色，2 号为绿色，3 号为红色</p>", "label": "A", "format": "html"}, {"text": "<p>1 is green, 2 is red and 3 is blue.</p><p>1 号为绿色，2 号为红色，3 号为蓝色</p>", "label": "B", "format": "html"}, {"text": "<p>1 is red, 2 is blue and 3 is green.</p><p>1 号为红色，2 号为蓝色，3 号为绿色</p>", "label": "C", "format": "html"}, {"text": "<p>1 is green, 2 is blue and 3 is red.</p><p>1 号为绿色，2 号为蓝色，3 号为红色</p>", "label": "D", "format": "html"}, {"text": "<p>1 is blue, 2 is red and 3 is green.</p><p>1 号为蓝色，2 号为红色，3 号为绿色</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 11:06:30','2026-05-13 10:10:58'),
	 (175583981568,1001,'Which piece completes the picture?以下哪一张图可以用于填补图片中的','{"text": "<p>Which piece completes the picture?</p><p>以下哪一张图可以用于填补图片中的空白？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_d0733d7c.png\\" alt=\\"20260512_d0733d7c.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_8883c7c8.png\\" alt=\\"20260512_8883c7c8.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_2c795317.png\\" alt=\\"20260512_2c795317.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_087c79ee.png\\" alt=\\"20260512_087c79ee.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_dcc0af5e.png\\" alt=\\"20260512_dcc0af5e.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_47130dab.png\\" alt=\\"20260512_47130dab.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 11:33:03','2026-05-13 10:10:58'),
	 (175621734400,1003,'A village with 12 houses has four straight roads a','{"text": "<p>A village with 12 houses has four straight roads and four circular roads. The map shows 11 of the houses. On each straight road there are 3 houses. On each circular road there are also 3 houses. Where is the 12th house? </p><p>一个村庄，有12间房子,还有4条直路和4条环行路。以下图片一共显示了11间房子。 每条直路上要有3间房子，每条环形路上也要有3间房子。请问第12间房子会在哪里？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_8082a6f3.png\\" alt=\\"20260512_8082a6f3.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>A</p>", "label": "A", "format": "html"}, {"text": "<p>B</p>", "label": "B", "format": "html"}, {"text": "<p>C</p>", "label": "C", "format": "html"}, {"text": "<p>D</p>", "label": "D", "format": "html"}, {"text": "<p>E</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 14:06:40','2026-05-13 10:10:58');
INSERT INTO mathcoe_db.questions (id,topic_id,title,content,question_type,`options`,answer,explanation,difficulty_level,source_year,tags,created_at,updated_at) VALUES
	 (175625986048,1001,'Five shapes are made by gluing cubes together. Whi','{"text": "<p>Five shapes are made by gluing cubes together. Which shape uses the most cubes?</p><p>把一些正方体粘合在一起可以制作成以下的五个形状。请问哪种形状使用的正方体最多？</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_bd2ea510.png\\" alt=\\"20260512_bd2ea510.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_8dee8732.png\\" alt=\\"20260512_8dee8732.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_3fd7d0b1.png\\" alt=\\"20260512_3fd7d0b1.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_e06e9e32.png\\" alt=\\"20260512_e06e9e32.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_ef448a10.png\\" alt=\\"20260512_ef448a10.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','E','{"text": "<p><br></p>", "format": "html"}',1,2020,'null','2026-05-12 14:23:58','2026-05-13 10:10:58'),
	 (175632171008,1004,'A number is written on each petal of two flowers. ','{"text": "<p>A number is written on each petal of two flowers. One petal is hidden. The sums of the numbers on the two flowers are equal. What number is written on the hidden petal? </p><p>两朵花的每片花瓣上都写有数字，其中一片花瓣被挡住了。如果两朵花上的数字之和是相等的，请问被挡住的那片花瓣上 的数字是什么？ </p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_86684c2d.png\\" alt=\\"20260512_86684c2d.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>0</p>", "label": "A", "format": "html"}, {"text": "<p>3</p>", "label": "B", "format": "html"}, {"text": "<p>5</p>", "label": "C", "format": "html"}, {"text": "<p>7</p>", "label": "D", "format": "html"}, {"text": "<p>1</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 14:49:08','2026-05-12 10:42:37'),
	 (175645642752,1001,'Which picture has the largest shaded area? 以下哪张图片中','{"text": "<p>Which picture has the largest shaded area? </p><p>以下哪张图片中的阴影部分面积最大?</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_ad499145.png\\" alt=\\"20260512_ad499145.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_e0b6b1a3.png\\" alt=\\"20260512_e0b6b1a3.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_161b06f6.png\\" alt=\\"20260512_161b06f6.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_ecbe00f6.png\\" alt=\\"20260512_ecbe00f6.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_b7028fc4.png\\" alt=\\"20260512_b7028fc4.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 15:43:57','2026-05-13 18:32:51'),
	 (175646400512,1002,'Mary wants to write the numbers 1, 2, 3, 4, 5 and ','{"text": "<p>Mary wants to write the numbers 1, 2, 3, 4, 5 and 6 inside the six squares of the figure. She wants<br> a different number in each square. She wants both the sum of the numbers in the blue squares and the sum of the numbers in the yellow squares to be 10. What number must she write in the square with the question mark?</p><p>Mary想把数字1,2,3,4,5,6写进下面的六个方格中，且每个方格中的数字都不同，除此之外，她想让蓝色方格里的数字之和与黄色方格里的数字之和都为10。请问她必须在标有问号的方格里写上什么数字?</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_97ea7fb7.png\\" alt=\\"20260512_97ea7fb7.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>1</p>", "label": "A", "format": "html"}, {"text": "<p>2</p>", "label": "B", "format": "html"}, {"text": "<p>3</p>", "label": "C", "format": "html"}, {"text": "<p>4</p>", "label": "D", "format": "html"}, {"text": "<p>5</p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 15:47:02','2026-05-13 18:32:51'),
	 (175648219136,1001,'The card was on the table. It is flipped over its ','{"text": "<p>The card was on the table. It is flipped over its top edge then flipped over its left edge. What does the </p><p>card look like now?</p><p>如图所示，桌子上摆放着一张卡片。该卡片沿着顶部的边缘进行折叠翻转，然后再沿着左侧的边缘折叠翻转后，请问该卡片会变成什么样子？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_70adaf20.png\\" alt=\\"20260512_70adaf20.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_0da118ee.png\\" alt=\\"20260512_0da118ee.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_d8dd40ad.png\\" alt=\\"20260512_d8dd40ad.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_e2c093af.png\\" alt=\\"20260512_e2c093af.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_7d3c0b92.png\\" alt=\\"20260512_7d3c0b92.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_50118ac4.png\\" alt=\\"20260512_50118ac4.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 15:54:26','2026-05-13 18:32:51'),
	 (175648722944,1004,'Grandmother has baked 12 cookies. She wants to giv','{"text": "<p>Grandmother has baked 12 cookies. She wants to give all the cookies to her 5 grandchildren. She also wants to give each grandchild the same number of cookies. How many extra cookies should she bake? </p><p>祖母烤了12块饼干，她想将所有饼干平均分配给她的5个孙子。请问她还需要再多烤几块饼干？</p><p><br></p>", "format": "html"}','single','[{"text": "<p>0</p>", "label": "A", "format": "html"}, {"text": "<p>1</p>", "label": "B", "format": "html"}, {"text": "<p>2</p>", "label": "C", "format": "html"}, {"text": "<p>3</p>", "label": "D", "format": "html"}, {"text": "<p>4</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 15:56:29','2026-05-13 18:32:51'),
	 (175650701312,1001,'Tom has 9 cards,as shown: He puts the cards on the','{"text": "<p>Tom has 9 cards,as shown: He puts the cards on the board so that each horizontal line and each vertical line countains three cards with three different shapes and three different number of shapes. He has already put three cards, as shown. Which card does he put on the grey square? </p><p>Tom有 9 张卡片，如图:</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_01a88ab1.png\\" alt=\\"20260512_01a88ab1.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p><p>他把卡片放在方格内，使得每个水平和垂直方向上都有三张不同形状和不同形状数目的卡片。他已经放了三张卡片了，如下图所示。请问他应该在灰色的方格内放入哪张卡片？ </p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_164a5636.png\\" alt=\\"20260512_164a5636.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_7f0d3667.png\\" alt=\\"20260512_7f0d3667.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_7969b92e.png\\" alt=\\"20260512_7969b92e.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_44d1f62c.png\\" alt=\\"20260512_44d1f62c.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_6a62e68f.png\\" alt=\\"20260512_6a62e68f.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_ca8402c4.png\\" alt=\\"20260512_ca8402c4.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 16:04:32','2026-05-13 10:10:58'),
	 (175651426304,1002,'Two identical trains, each with 31 cars, are trave','{"text": "<p>Two identical trains, each with 31 cars, are traveling in opposite directions. When car No. 19 of one train is opposite car No. 19 of the other, which car is opposite car No. 12? </p><p>两列相同的火车，各有31节车厢，它们朝相反的方向行驶。当其中一列火车的19号车厢与另一列火车的19号车厢相对时，几号车厢会与12号车厢相对？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_2daec0da.png\\" alt=\\"20260512_2daec0da.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>7</p>", "label": "A", "format": "html"}, {"text": "<p>12</p>", "label": "B", "format": "html"}, {"text": "<p>21</p>", "label": "C", "format": "html"}, {"text": "<p>26</p>", "label": "D", "format": "html"}, {"text": "<p>31</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 16:07:29','2026-05-12 10:42:37'),
	 (175652372480,1002,'Mark the Bee can walk only on grey cells. In how m','{"text": "<p>Mark the Bee can walk only on grey cells. In how many ways could you colour exactly two white cells grey so that Mark can walk from A to B? </p><p>有一只小蜜蜂只能在灰色的蜂房上行走。请问你可以通过几种方式将其中两个白色蜂房涂为灰色，以便小蜜蜂可以从 A 行走到 B ？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_d2e6e6e3.png\\" alt=\\"20260512_d2e6e6e3.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p><p> </p>", "format": "html"}','single','[{"text": "<p>3</p>", "label": "A", "format": "html"}, {"text": "<p>4</p>", "label": "B", "format": "html"}, {"text": "<p>5</p>", "label": "C", "format": "html"}, {"text": "<p>6</p>", "label": "D", "format": "html"}, {"text": "<p>7</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 16:11:20','2026-05-13 18:32:51'),
	 (175652900864,1002,'An arrow pointing from one person to another means','{"text": "<p>An arrow pointing from one person to another means that the first person is taller than the second. For example, person B is taller than person A. Who is the shortest? </p><p>如图所示，当一个箭头从一个人指向另一个人时，表示第一个人比第二个人高。例如，箭头从 B 指向 A ，表示 B 比 A 高。请问谁是当中最矮的？ </p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_d1d90a8a.png\\" alt=\\"20260512_d1d90a8a.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>A</p>", "label": "A", "format": "html"}, {"text": "<p>B</p>", "label": "B", "format": "html"}, {"text": "<p>C</p>", "label": "C", "format": "html"}, {"text": "<p>D</p>", "label": "D", "format": "html"}, {"text": "<p>E</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 16:13:29','2026-05-13 18:32:51');
INSERT INTO mathcoe_db.questions (id,topic_id,title,content,question_type,`options`,answer,explanation,difficulty_level,source_year,tags,created_at,updated_at) VALUES
	 (175653855232,1004,'There are some apples and 8 pears in a basket, eac','{"text": "<p>There are some apples and 8 pears in a basket, each of them green or yellow. There are three more </p><p>apples than the total number of green fruit. There are 6 yellow pears. How many yellow apples are there in </p><p>the basket? </p><p>一个篮子里有一些苹果和8个梨，它们要么是绿色，要么是黄色。苹果的数量比绿色水果总数多了三个。如果篮子里有6个黄色的梨，请问篮子里有几个黄色的苹果？ </p>", "format": "html"}','single','[{"text": "<p>4</p>", "label": "A", "format": "html"}, {"text": "<p>5</p>", "label": "B", "format": "html"}, {"text": "<p>6</p>", "label": "C", "format": "html"}, {"text": "<p>7</p>", "label": "D", "format": "html"}, {"text": "<p>8</p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 16:17:22','2026-05-13 18:32:51'),
	 (175655014400,1002,'Roo wrote each of the numbers 1,2,3,4 and 5 in one','{"text": "<p>Roo wrote each of the numbers 1,2,3,4 and 5 in one of the circles so that the sum of the numbers in the row is equal to the sum of the numbers in the column. What number could be written in the circle with the question mark? </p><p>Roo在每个圆中分别写下了数字1、2、3、4和5，因此横行中的数字之和等于竖列中的数字之和。请问图中画问号的圆中是什么数字？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_e5083f79.png\\" alt=\\"20260512_e5083f79.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>Only 5 </p><p>只有 5</p>", "label": "A", "format": "html"}, {"text": "<p>2, 3 or 4</p><p>2, 3 或 4</p>", "label": "B", "format": "html"}, {"text": "<p>Only 3</p><p>只有 3</p>", "label": "C", "format": "html"}, {"text": "<p>Only 1 or 3</p><p>只有 1 或 3</p>", "label": "D", "format": "html"}, {"text": "<p>1, 3 or 5</p><p>1, 3 或 5</p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 16:22:05','2026-05-13 10:10:58'),
	 (175655776256,1002,'Six different numbers chosen from 1 to 9 are writt','{"text": "<p>Six different numbers chosen from 1 to 9 are written on the faces of a cube, one number on each face. </p><p>The sums of numbers on each pair of opposite faces are equal. Which number could be on the face opposite to </p><p>the face with number 5? </p><p>从1到9中选择六个不同的数字写在正方体的表面上，且每一面只写一个数字。如果每一个数字与它相对面上的数字总和是相等的，请问哪个数字将会出现在数字5相对的面上？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260512_c0bdc64d.png\\" alt=\\"20260512_c0bdc64d.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>3</p>", "label": "A", "format": "html"}, {"text": "<p>5</p>", "label": "B", "format": "html"}, {"text": "<p>6</p>", "label": "C", "format": "html"}, {"text": "<p>7</p>", "label": "D", "format": "html"}, {"text": "<p>9</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 16:25:11','2026-05-13 18:32:51'),
	 (175656480768,1004,'John and Olivia exchanged sweets. First, John gave','{"text": "<p>John and Olivia exchanged sweets. First, John gave Olivia as many sweets as Olivia had. Then, Olivia gave John as many sweets as John had after the first exchange. After these two exchanges, each had 4 sweets. How many sweets did John have at the beginning? </p><p>John和Olivia互相交换糖果。首先，John给Olivia的糖果数量是Olivia原本有的糖果数量。然后，Olivia给John的糖果数量是第一次交换后John还剩的糖果数量。经过这两次交换后，每个人都有4颗糖果。请问John一开始拥有多少颗糖果？</p>", "format": "html"}','single','[{"text": "<p>6</p>", "label": "A", "format": "html"}, {"text": "<p>5</p>", "label": "B", "format": "html"}, {"text": "<p>4</p>", "label": "C", "format": "html"}, {"text": "<p>3</p>", "label": "D", "format": "html"}, {"text": "<p>2</p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2020,'null','2026-05-12 16:28:03','2026-05-13 18:32:51'),
	 (175924961280,1001,'A kangaroo laid out 3 sticks like this to make a s','{"text": "<p>A kangaroo laid out 3 sticks like this <img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_693e2924.png\\" alt=\\"20260513_693e2924.png\\" data-href=\\"\\" style=\\"width: 99.00px;height: 15px;\\"/>to make a shape. It’s not allowed to break or to bend the sticks. Which shape could the kangaroo make? </p><p>一只袋鼠用三根这样的棍子<img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_89df6e74.png\\" alt=\\"20260513_89df6e74.png\\" data-href=\\"\\" style=\\"width: 99.00px;height: 15px;\\"/>来摆图形。不允许折断或折弯棍子，袋鼠可以摆出下列哪个图形？</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_e15024d4.png\\" alt=\\"20260513_e15024d4.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_bd6c3845.png\\" alt=\\"20260513_bd6c3845.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_f2cb4517.png\\" alt=\\"20260513_f2cb4517.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_cb4bbc98.png\\" alt=\\"20260513_cb4bbc98.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_fb5a729b.png\\" alt=\\"20260513_fb5a729b.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 10:40:30','2026-05-13 10:10:58'),
	 (175926296576,1001,'Four identical pieces of paper are placed as shown','{"text": "<p>Four identical pieces of paper are placed as shown. Michael wants to punch a hole that goes through all four pieces. At which point should Michael punch the hole? </p><p>将四张相同的纸张摆放如下。Michael 想打一个洞将四张纸全部穿过。请问Michael 应该把洞打在哪个点的位置？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_e003f078.png\\" alt=\\"20260513_e003f078.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>A</p>", "label": "A", "format": "html"}, {"text": "<p>B</p>", "label": "B", "format": "html"}, {"text": "<p>C</p>", "label": "C", "format": "html"}, {"text": "<p>D</p>", "label": "D", "format": "html"}, {"text": "<p>E</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 10:45:56','2026-05-13 18:32:51'),
	 (175928467456,1001,'Ella puts on this t-shirt and stands in front of a','{"text": "<p>Ella puts on this t-shirt and stands in front of a mirror. Which of these images does she see in the mirror? </p><p>Ella 穿着下方的T恤站在镜子前，请问她在镜子中看到的图像是哪一个？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_7f4f8d1e.png\\" alt=\\"20260513_7f4f8d1e.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_1955bc44.png\\" alt=\\"20260513_1955bc44.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_e3cad9c7.png\\" alt=\\"20260513_e3cad9c7.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_9c418e1a.png\\" alt=\\"20260513_9c418e1a.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_46cff0ce.png\\" alt=\\"20260513_46cff0ce.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_0d1cde9e.png\\" alt=\\"20260513_0d1cde9e.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 10:54:46','2026-05-13 18:32:51'),
	 (175930781696,1004,'The picture shows 2 mushrooms. What is the differe','{"text": "<p>The picture shows 2 mushrooms. What is the difference between their heights? </p><p>下面两个蘑菇的高度相差多少？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_a0e791f5.png\\" alt=\\"20260513_a0e791f5.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>4</p>", "label": "A", "format": "html"}, {"text": "<p>5</p>", "label": "B", "format": "html"}, {"text": "<p>6</p>", "label": "C", "format": "html"}, {"text": "<p>11</p>", "label": "D", "format": "html"}, {"text": "<p>17</p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 11:04:11','2026-05-13 18:32:51'),
	 (175931551744,1003,'Which of the paths shown in the pictures is the lo','{"text": "<p>Which of the paths shown in the pictures is the longest? </p><p>下列哪张图显示的路径最长？</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_da5773be.png\\" alt=\\"20260513_da5773be.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_905508b9.png\\" alt=\\"20260513_905508b9.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_0d50ff4a.png\\" alt=\\"20260513_0d50ff4a.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_491ed39c.png\\" alt=\\"20260513_491ed39c.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_a75bf67f.png\\" alt=\\"20260513_a75bf67f.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 11:07:19','2026-05-13 18:32:51'),
	 (175932424192,1002,'The pink tower is taller than the red tower but sh','{"text": "<p>The pink tower is taller than the red tower but shorter than the green tower. The silver tower is taller than the green tower. Which tower is the tallest? </p><p>粉色的塔比红色的塔高，但比绿色的塔矮，银色的塔比绿色的塔高。请问哪座塔最高？</p>", "format": "html"}','single','[{"text": "<p>pink tower </p><p>粉色的塔</p>", "label": "A", "format": "html"}, {"text": "<p>green tower</p><p>绿色的塔</p>", "label": "B", "format": "html"}, {"text": "<p>red tower</p><p>红色的塔</p>", "label": "C", "format": "html"}, {"text": "<p>silver tower</p><p>银色的塔</p>", "label": "D", "format": "html"}, {"text": "<p>impossible to decide</p><p>无法确定</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 11:10:52','2026-05-13 18:32:51');
INSERT INTO mathcoe_db.questions (id,topic_id,title,content,question_type,`options`,answer,explanation,difficulty_level,source_year,tags,created_at,updated_at) VALUES
	 (175933206528,1003,'These children are standing in a line. Some are fa','{"text": "<p>These children are standing in a line. Some are facing forwards and others are facing backwards. How many children are holding another child’s hand with their right hand? </p><p>图中孩子们站成一排。有的面朝前，有的面朝后。请问有多少个孩子是用右手挽着旁边的孩子？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_02a0df1d.png\\" alt=\\"20260513_02a0df1d.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>2</p>", "label": "A", "format": "html"}, {"text": "<p>3</p>", "label": "B", "format": "html"}, {"text": "<p>4</p>", "label": "C", "format": "html"}, {"text": "<p>5</p>", "label": "D", "format": "html"}, {"text": "<p>6</p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 11:14:03','2026-05-13 10:10:58'),
	 (175934386176,1004,'In the Kangaroo constellation, all stars have a nu','{"text": "<p>In the Kangaroo constellation, all stars have a number greater than 3 and their sum is 20. Which is the Kangaroo constellation? </p><p>在袋鼠星座中，所有的星星上都有一个大于3的数字，而且它们的总和是20。请问哪个是袋鼠星座？</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_bca93f9f.png\\" alt=\\"20260513_bca93f9f.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_fe921e92.png\\" alt=\\"20260513_fe921e92.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_e85dbbb7.png\\" alt=\\"20260513_e85dbbb7.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_461f8b84.png\\" alt=\\"20260513_461f8b84.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_03d5bc4e.png\\" alt=\\"20260513_03d5bc4e.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 11:18:51','2026-05-13 18:32:51'),
	 (175934844928,1001,'Edmund cut a ribbon as shown in the picture. How m','{"text": "<p>Edmund cut a ribbon as shown in the picture. How many pieces of the ribbon did he finish with? </p><p>如图所示，Edmund 剪断了一根丝带。请问剪完后这根丝带变成了几段？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_794ad144.png\\" alt=\\"20260513_794ad144.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>9</p>", "label": "A", "format": "html"}, {"text": "<p>10</p>", "label": "B", "format": "html"}, {"text": "<p>11</p>", "label": "C", "format": "html"}, {"text": "<p>12</p>", "label": "D", "format": "html"}, {"text": "<p>13</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 11:20:43','2026-05-13 18:32:51'),
	 (175935619072,1003,'Rose the cat walks along the wall. She starts at p','{"text": "<p>Rose the cat walks along the wall. She starts at point B and follows the direction of the arrows shown in the picture. The cat walks a total of 20 metres. Where does she end up?</p><p>小猫Rose 沿着墙壁走路。它从B点出发，沿着图中箭头方向行走，一共走了20米。请问小猫最后停在了哪个点上？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_b9d0bd7e.png\\" alt=\\"20260513_b9d0bd7e.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>A</p>", "label": "A", "format": "html"}, {"text": "<p>B</p>", "label": "B", "format": "html"}, {"text": "<p>C</p>", "label": "C", "format": "html"}, {"text": "<p>D</p>", "label": "D", "format": "html"}, {"text": "<p>E</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 11:23:52','2026-05-13 18:32:51'),
	 (175976304640,1002,'Tom encodes words using the board shown. For examp','{"text": "<p>Tom encodes words using the board shown. For example, the word PIZZA has the code A2 A4 C1 C1 B2. What word did Tom encode as B3 B2 C4 D2? </p><p>Tom 用如图所示的字母板给单词进行编码。比如单词PIZZA 的代码为A2A4C1C1B2。请问代码为B3B2C4D2 的单词是哪一个？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_75ca0e5a.png\\" alt=\\"20260513_75ca0e5a.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>MAZE</p>", "label": "A", "format": "html"}, {"text": "<p>MASK</p>", "label": "B", "format": "html"}, {"text": "<p>MILK</p>", "label": "C", "format": "html"}, {"text": "<p>MATE</p>", "label": "D", "format": "html"}, {"text": "<p>MATH</p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:09:25','2026-05-13 10:10:58'),
	 (175978975232,1003,'Julia has two pots with flowers, as shown. She kee','{"text": "<p>Julia has two pots with flowers, as shown. She keeps the flowers exactly where they are. She buys more flowers and puts them in the pots. After that each pot has the same number of each type of flower. What is the smallest number of flowers she needs to buy? </p><p>Julia 有两盆花，如图所示。她把花放在原处后，又买了一些花放进了花盆里。现在两个花盆里每种类型的花的数量都相同。请问Julia 最少需要买多少枝花？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_7b2ce429.png\\" alt=\\"20260513_7b2ce429.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>2</p>", "label": "A", "format": "html"}, {"text": "<p>4</p>", "label": "B", "format": "html"}, {"text": "<p>6</p>", "label": "C", "format": "html"}, {"text": "<p>8</p>", "label": "D", "format": "html"}, {"text": "<p>10</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:20:17','2026-05-13 18:32:51'),
	 (175979556864,1004,'Julie and Angela played “kangball”, a ball game. E','{"text": "<p>Julie and Angela played “kangball”, a ball game. Each goal in their game scores 2 points. Julie scored 5 goals and Angela scored 9 goals. How many more points than Julie did Angela score? </p><p>Julie 和Angela 玩一种叫做 ”kangball” 的球类游戏，每进一球得2分。Julie 进了5个球，Angela进了9个球。请问Angela 比Julie 多得几分？</p>", "format": "html"}','single','[{"text": "<p>4</p>", "label": "A", "format": "html"}, {"text": "<p>6</p>", "label": "B", "format": "html"}, {"text": "<p>8</p>", "label": "C", "format": "html"}, {"text": "<p>10</p>", "label": "D", "format": "html"}, {"text": "<p>12</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:22:39','2026-05-13 18:32:51'),
	 (175980679168,1001,'Which figure can be made from these two pieces? 下列','{"text": "<p>Which figure can be made from these two pieces? </p><p>下列两张碎片可以组成哪个图形？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_ec6e09f5.png\\" alt=\\"20260513_ec6e09f5.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_86ff22a8.png\\" alt=\\"20260513_86ff22a8.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_221dd2d0.png\\" alt=\\"20260513_221dd2d0.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_25e04e68.png\\" alt=\\"20260513_25e04e68.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_61138972.png\\" alt=\\"20260513_61138972.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_d034b6a6.png\\" alt=\\"20260513_d034b6a6.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:27:13','2026-05-13 18:32:51'),
	 (175981756416,1002,'The picture shows the five houses of five friends ','{"text": "<p>The picture shows the five houses of five friends and their school. The school is the largest building in the picture. To go to school, Doris and Ali walk past Leo’s house. Eva walks past Chole’s house. Which is Eva’s house? </p><p>下图展示了五个朋友的家和学校的位置。学校是图中最大的建筑。上学路上Doris 和Ali 会经过Leo 的家，Eva 会经过Chole 的家。请问哪一个是Eva的家？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_49fbcac3.png\\" alt=\\"20260513_49fbcac3.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_cb362989.png\\" alt=\\"20260513_cb362989.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_258d9770.png\\" alt=\\"20260513_258d9770.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_fcf84582.png\\" alt=\\"20260513_fcf84582.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_670cf02c.png\\" alt=\\"20260513_670cf02c.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_d7c86079.png\\" alt=\\"20260513_d7c86079.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:31:36','2026-05-13 18:32:51'),
	 (175983218688,1002,'The kangaroo had two branches for lunch. Each bran','{"text": "<p>The kangaroo had two branches for lunch. Each branch had 10 leaves. The kangaroo ate some leaves from one branch. Then, from the second branch, it ate as many leaves as were left on the first branch. How many leaves in total were left on the two branches? </p><p>袋鼠中午吃了两根树枝上的一些叶子。每根树枝上有10片叶子，袋鼠先后吃了第一根和第二根树枝上的几片叶子。吃的第二根树枝上叶子的数量正好是第一根树枝上吃剩的叶子数量。请问这两根树枝上一共剩下多少片叶子？</p>", "format": "html"}','single','[{"text": "<p>5</p>", "label": "A", "format": "html"}, {"text": "<p>6</p>", "label": "B", "format": "html"}, {"text": "<p>8</p>", "label": "C", "format": "html"}, {"text": "<p>10</p>", "label": "D", "format": "html"}, {"text": "<p>15</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:37:33','2026-05-13 18:32:51');
INSERT INTO mathcoe_db.questions (id,topic_id,title,content,question_type,`options`,answer,explanation,difficulty_level,source_year,tags,created_at,updated_at) VALUES
	 (175984136192,1001,'Mara built the square by using four of the followi','{"text": "<p>Mara built the square by using four of the following five shapes. Which shape was not used? </p><p>Mara用五个选项中的其中四个碎片来组成下面的正方形。请问哪一个形状没有被用到？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_4141aa0d.png\\" alt=\\"20260513_4141aa0d.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_5771be6d.png\\" alt=\\"20260513_5771be6d.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_2b0ff1d1.png\\" alt=\\"20260513_2b0ff1d1.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_c02750bf.png\\" alt=\\"20260513_c02750bf.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_54298b82.png\\" alt=\\"20260513_54298b82.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_ce01960e.png\\" alt=\\"20260513_ce01960e.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:41:17','2026-05-13 18:32:51'),
	 (175984816128,1004,'The cards shown are placed into two boxes. The sum','{"text": "<p>The cards shown are placed into two boxes. The sums of the numbers in each box are the same. Which number must be in the box with the number 4? </p><p>将图示卡片放在两个盒子中，要求每个盒子中的数字之和相等。请问哪个数字一定和4放在一起？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_c9b653dd.png\\" alt=\\"20260513_c9b653dd.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>only3</p><p>只有3</p>", "label": "A", "format": "html"}, {"text": "<p>only 5</p><p>只有5</p>", "label": "B", "format": "html"}, {"text": "<p>only 6</p><p>只有6</p>", "label": "C", "format": "html"}, {"text": "<p>only 5 or 6</p><p>只有 5 或 6</p>", "label": "D", "format": "html"}, {"text": "<p>impossible to determine</p><p>无法确定</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:44:03','2026-05-13 18:32:51'),
	 (175986855936,1004,'Every time the witch has 3 apples she turns them i','{"text": "<p>Every time the witch has 3 apples she turns them in to 1 banana. Every time she has 3 bananas she turns them in to 1 apple. What will she finish with if she starts with 4 apples and 5 bananas? </p><p>每当女巫有3个苹果，她就把3个苹果变成1个香蕉；每当女巫有3个香蕉，她就把这3个香蕉变成1个苹果。</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_14578392.png\\" alt=\\"20260513_14578392.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p><p>如果女巫刚开始有4个苹果和5个香蕉，那么她最后会剩下什么？</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_afc6297e.png\\" alt=\\"20260513_afc6297e.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_6b078dcd.png\\" alt=\\"20260513_6b078dcd.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_7c94b4f4.png\\" alt=\\"20260513_7c94b4f4.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_19dddba3.png\\" alt=\\"20260513_19dddba3.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_3ff95692.png\\" alt=\\"20260513_3ff95692.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:52:21','2026-05-13 18:32:51'),
	 (175987228672,1002,'Three girls and two boys were dancing. They danced','{"text": "<p>Three girls and two boys were dancing. They danced in pairs so that each girl danced with each boy for exactly one minute. At any time, there was only one pair on the dance floor. For how many minutes did they dance? </p><p>三个女孩和两个男孩在跳舞。男孩和女孩搭档跳舞，每个男孩和每个女孩都恰好跳一分钟，每次舞池中只能有一对搭档。请问他们一共跳了几分钟？</p>", "format": "html"}','single','[{"text": "<p>5</p>", "label": "A", "format": "html"}, {"text": "<p>6</p>", "label": "B", "format": "html"}, {"text": "<p>8</p>", "label": "C", "format": "html"}, {"text": "<p>9</p>", "label": "D", "format": "html"}, {"text": "<p>10</p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:53:52','2026-05-13 18:32:51'),
	 (175988211712,1001,'The picture shows two cogs, each with a black toot','{"text": "<p>The picture shows two cogs, each with a black tooth. </p><p>下图中有两个齿轮，每个齿轮上都有一个黑色的轮齿。请问小齿轮转动一周后，黑色轮齿会在什么位置？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_1e5b2a74.png\\" alt=\\"20260513_1e5b2a74.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_a77e3121.png\\" alt=\\"20260513_a77e3121.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_34472d43.png\\" alt=\\"20260513_34472d43.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_fa94657f.png\\" alt=\\"20260513_fa94657f.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_12a18066.png\\" alt=\\"20260513_12a18066.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_ed60a4b9.png\\" alt=\\"20260513_ed60a4b9.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:57:52','2026-05-13 18:32:51'),
	 (175988445184,1004,'Kangie eats only apples on Monday, Wednesday and F','{"text": "<p>Kangie eats only apples on Monday, Wednesday and Friday. On Tuesdays and Thursdays he eats only mangoes. He eats either 2 apples or 3 mangoes a day. On Saturdays and Sundays he eats nothing. How many pieces of fruit does Kangie eat in two weeks? </p><p>Kangie在周一、周三和周五只吃苹果；在周二和周四只吃芒果。他一天吃2个苹果或3个芒果，且在周六和周日什么都不吃。请问Kangie在两周内吃了多少个水果？</p>", "format": "html"}','single','[{"text": "<p>12</p>", "label": "A", "format": "html"}, {"text": "<p>16</p>", "label": "B", "format": "html"}, {"text": "<p>18</p>", "label": "C", "format": "html"}, {"text": "<p>20</p>", "label": "D", "format": "html"}, {"text": "<p>24</p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 14:58:49','2026-05-13 10:10:58'),
	 (175989141504,1002,'Each participant in a cooking contest baked one tr','{"text": "<p>Each participant in a cooking contest baked one tray of cookies like the one shown. What is the smallest number of trays of cookies needed to make the following plate? </p><p>一次烹饪比赛中，每个选手都烤了一盘如下图所示的饼干。</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_40a3467f.png\\" alt=\\"20260513_40a3467f.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p><p>要组成下图所示的饼干拼盘，至少需要几个选手烤的饼干？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_1748e5ff.png\\" alt=\\"20260513_1748e5ff.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>1</p>", "label": "A", "format": "html"}, {"text": "<p>2</p>", "label": "B", "format": "html"}, {"text": "<p>3</p>", "label": "C", "format": "html"}, {"text": "<p>4</p>", "label": "D", "format": "html"}, {"text": "<p>5</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 15:01:39','2026-05-13 18:32:51'),
	 (175989678080,1002,'Stan has five toys: a ball, a set of blocks, a gam','{"text": "<p>Stan has five toys: a ball, a set of blocks, a game, a puzzle and a car. He puts each toy on a different shelf of the bookcase. The ball is higher than the blocks and lower than the car. The game is directly above the ball. On which shelf can the puzzle not be placed? </p><p>Stan有五个玩具:一个球、一套积木、一个游戏机、一个拼图和一辆汽车。他把每个玩具放在书架不同的层。球的位置比积木高，比汽车低，游戏机在球的上一层。请问拼图不能放在书架的哪一层？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260513_fdc11912.png\\" alt=\\"20260513_fdc11912.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>1</p>", "label": "A", "format": "html"}, {"text": "<p>2</p>", "label": "B", "format": "html"}, {"text": "<p>3</p>", "label": "C", "format": "html"}, {"text": "<p>4</p>", "label": "D", "format": "html"}, {"text": "<p>5</p>", "label": "E", "format": "html"}]','C','{"text": "", "format": "html"}',1,2021,'null','2026-05-13 15:03:50','2026-05-13 18:32:51'),
	 (176074420224,1004,'Which box contains the most triangles?下面哪个盒子里的三角形最','{"text": "<p>Which box contains the most triangles?</p><p>下面哪个盒子里的三角形最多？</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_6c3339c0.png\\" alt=\\"20260514_6c3339c0.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_e897e7a2.png\\" alt=\\"20260514_e897e7a2.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_7d7c2557.png\\" alt=\\"20260514_7d7c2557.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_272a1821.png\\" alt=\\"20260514_272a1821.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_f86d12bc.png\\" alt=\\"20260514_f86d12bc.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:48:39','2026-05-13 18:32:51'),
	 (176074936320,1001,'Arek cuts this picture in half and puts the two pi','{"text": "<p>Arek cuts this picture in half and puts the two pieces together. Which option shows the two pieces of Arek''s picture?</p><p>Arek 将下面这张照片剪成两半，然后重新拼接在一起。下面哪个选项是 Arek 拼接出来的形状？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_1c65130d.png\\" alt=\\"20260514_1c65130d.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_732e2eeb.png\\" alt=\\"20260514_732e2eeb.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_d62ba50c.png\\" alt=\\"20260514_d62ba50c.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_0d1f436b.png\\" alt=\\"20260514_0d1f436b.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_81344373.png\\" alt=\\"20260514_81344373.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_ad69315c.png\\" alt=\\"20260514_ad69315c.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:50:45','2026-05-13 18:32:51');
INSERT INTO mathcoe_db.questions (id,topic_id,title,content,question_type,`options`,answer,explanation,difficulty_level,source_year,tags,created_at,updated_at) VALUES
	 (176075087872,1001,'The picture shows 5 identical bricks. How many bri','{"text": "<p>The picture shows 5 identical bricks. How many bricks are touching exactly 3 other bricks?</p><p>图中有 5 块相同的砖。其中有几块砖恰好挨着另外 3 块砖？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_3c0928c6.png\\" alt=\\"20260514_3c0928c6.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>1</p>", "label": "A", "format": "html"}, {"text": "<p>2</p>", "label": "B", "format": "html"}, {"text": "<p>3</p>", "label": "C", "format": "html"}, {"text": "<p>4</p>", "label": "D", "format": "html"}, {"text": "<p>5</p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:51:22','2026-05-13 18:32:51'),
	 (176075251712,1003,'One sandwich and one juice together cost 12 euro. ','{"text": "<p>One sandwich and one juice together cost 12 euro. One sandwich and two juices together cost 14 euro. How much does one juice cost?</p><p>一份三明治和一杯果汁加起来共 12 元，一份三明治和两杯果汁加起来共 14 元。那么一杯果汁多少钱？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_1fd44657.png\\" alt=\\"20260514_1fd44657.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>1</p>", "label": "A", "format": "html"}, {"text": "<p>2</p>", "label": "B", "format": "html"}, {"text": "<p>3</p>", "label": "C", "format": "html"}, {"text": "<p>4</p>", "label": "D", "format": "html"}, {"text": "<p>5</p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:52:02','2026-05-13 18:32:51'),
	 (176075476992,1002,'There has to be 2 coins in each row and each colum','{"text": "<p>There has to be 2 coins in each row and each column. Where do you need to put the final coin?</p><p>要使每行和每列都必须有 2 枚硬币。那么最后一枚硬币应该放在哪个位置？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_b1f409ef.png\\" alt=\\"20260514_b1f409ef.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>A</p>", "label": "A", "format": "html"}, {"text": "<p>B</p>", "label": "B", "format": "html"}, {"text": "<p>C</p>", "label": "C", "format": "html"}, {"text": "<p>D</p>", "label": "D", "format": "html"}, {"text": "<p>E</p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:52:57','2026-05-13 18:32:51'),
	 (176075476999,1004,'A monkey has torn a piece from Captain Jack’s map.','{"text": "<p>A monkey has torn a piece from Captain Jack’s map. Which is the missing piece?</p><p>一只猴子把Jack 船长的地图撕掉了一块。下面哪块是地图缺失的部分？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_de60ef5f.png\\" alt=\\"20260514_de60ef5f.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_6d55bae7.png\\" alt=\\"20260514_6d55bae7.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_8f70c607.png\\" alt=\\"20260514_8f70c607.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_08e7f2db.png\\" alt=\\"20260514_08e7f2db.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_6ff393fd.png\\" alt=\\"20260514_6ff393fd.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_d3e17549.png\\" alt=\\"20260514_d3e17549.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:59:08','2026-05-13 18:32:51'),
	 (176075640832,1001,'Peter puts the 4 puzzle pieces shown together to m','{"text": "<p>Peter puts the 4 puzzle pieces shown together to make a square. Which picture can he make?</p><p>Peter 将下面 4 片拼图拼在一起组成一个正方形。请问他能拼出选项中的哪幅图？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_65b7f559.png\\" alt=\\"20260514_65b7f559.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_aa4a37e0.png\\" alt=\\"20260514_aa4a37e0.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_8fd352fe.png\\" alt=\\"20260514_8fd352fe.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_5c6fa78c.png\\" alt=\\"20260514_5c6fa78c.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_2f44f308.png\\" alt=\\"20260514_2f44f308.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_883414c6.png\\" alt=\\"20260514_883414c6.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','B','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:53:37','2026-05-13 18:32:51'),
	 (176075825152,1001,'Some ink spilled on a piece of squared paper, as s','{"text": "<p>Some ink spilled on a piece of squared paper, as shown in the picture. How many of the squares have ink on them?</p><p>如图所示，墨水洒在了一张方格纸上。请问有多少个小方格沾上了墨水？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_f76b92ef.png\\" alt=\\"20260514_f76b92ef.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>16</p>", "label": "A", "format": "html"}, {"text": "<p>17</p>", "label": "B", "format": "html"}, {"text": "<p>18</p>", "label": "C", "format": "html"}, {"text": "<p>19</p>", "label": "D", "format": "html"}, {"text": "<p>20</p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:54:22','2026-05-13 18:32:51'),
	 (176076427264,1001,'Kanga wrote down a number and then covered each di','{"text": "<p>Kanga wrote down a number and then covered each digit with a shape. Different digits were covered by different shapes, and the same digits were covered by the same shape. Which number could be written under these shapes?</p><p>小袋鼠写下一个数，然后用各种形状盖住每个数位上的数字。不同形状下方的数字不同，相同形状下方的数字相同。请问这些形状下方可能写有哪个数？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_d9c27efd.png\\" alt=\\"20260514_d9c27efd.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>34426</p>", "label": "A", "format": "html"}, {"text": "<p>34526</p>", "label": "B", "format": "html"}, {"text": "<p>34423</p>", "label": "C", "format": "html"}, {"text": "<p>34424</p>", "label": "D", "format": "html"}, {"text": "<p>32446</p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 20:56:49','2026-05-13 18:32:51'),
	 (176078483456,1003,'One animal sleeps in each of the baskets. The koal','{"text": "<p>One animal sleeps in each of the baskets. The koala and the fox are sleeping in baskets with the same pattern and shape. The kangaroo and the ostrich have the same pattern on their baskets. Which basket is the puppy sleeping in?</p><p>每个篮子里都有一只动物在睡觉。考拉和狐狸睡在图案和形状都相同的篮子里。袋鼠和鸵鸟睡在图案相同的篮子里。那么小狗睡在哪个篮子里？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_18f60776.png\\" alt=\\"20260514_18f60776.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p>1号篮子</p>", "label": "A", "format": "html"}, {"text": "<p>2号篮子</p>", "label": "B", "format": "html"}, {"text": "<p>3号篮子</p>", "label": "C", "format": "html"}, {"text": "<p>4号篮子</p>", "label": "D", "format": "html"}, {"text": "<p>5号篮子</p>", "label": "E", "format": "html"}]','E','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 21:05:11','2026-05-14 14:13:09'),
	 (176078684160,1002,'Kanga wants to reach the koala without going throu','{"text": "<p>Kanga wants to reach the koala without going through any of the coloured squares. Which route could she take?</p><p>袋鼠想找考拉玩，但不想经过任何一个彩色方块。她可以走下面哪条路线？</p><p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_f69282d0.png\\" alt=\\"20260514_f69282d0.png\\" data-href=\\"\\" style=\\"width: 100%;\\"/></p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_1ea18691.png\\" alt=\\"20260514_1ea18691.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_2ab24f72.png\\" alt=\\"20260514_2ab24f72.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_7d4e6b7b.png\\" alt=\\"20260514_7d4e6b7b.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_efeb8940.png\\" alt=\\"20260514_efeb8940.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_ab183fcd.png\\" alt=\\"20260514_ab183fcd.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','A','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 21:06:00','2026-05-13 18:32:51'),
	 (176078913536,1004,'In one of the pictures below, a shape is used that','{"text": "<p>In one of the pictures below, a shape is used that cannot be seen in the others. In which picture is it?</p><p>下面哪张图片中，使用了其他图片中没有用到的形状？</p>", "format": "html"}','single','[{"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_71a9140e.png\\" alt=\\"20260514_71a9140e.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "A", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_9e21cd0d.png\\" alt=\\"20260514_9e21cd0d.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "B", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_8df86efc.png\\" alt=\\"20260514_8df86efc.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "C", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_aa8b7aea.png\\" alt=\\"20260514_aa8b7aea.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "D", "format": "html"}, {"text": "<p><img src=\\"http://124.222.75.232:8000/api/v1/static/uploads/20260514_2e692aa3.png\\" alt=\\"20260514_2e692aa3.png\\" data-href=\\"\\" style=\\"width: 50%;\\"/></p>", "label": "E", "format": "html"}]','D','{"text": "", "format": "html"}',1,2022,'null','2026-05-13 21:06:56','2026-05-13 18:32:51');
